from transformers import pipeline
import torch

device = 0 if torch.cuda.is_available() else -1


summarizer = pipeline(
    "summarization",
    model = "facebook/bart-large-cnn",
    device = device
)

def summarize_chunk(text, max_length=130, min_length=30):
    result = summarizer(text,
                        max_length=max_length,
                        min_length=min_length,
                        do_sample=False)
    return result[0]["summary_text"]

def chunk_text(text, max_words=500):
    sentences = text.split(". ")
    sentences = [s + "." for s in sentences]

    chunks = []
    current_chunk = ""

    for sentence in sentences:
        word_count_if_added = len((current_chunk + sentence).split())

        if word_count_if_added <= max_words:
            current_chunk += sentence + " "
        else:
            chunks.append(current_chunk)
            current_chunk = sentence + " "

    if current_chunk:
        chunks.append(current_chunk)
    return chunks

def summarize_long_text(text, max_words=500, max_length=130, min_length=30):
    chunks = chunk_text(text, max_words=max_words)
    chunk_summaries = [summarize_chunk(c, max_length, min_length) for c in chunks]
    combined = " ".join(chunk_summaries)
    if(len(combined.split()) > 500):
        combined = summarize_chunk(combined, max_length=150, min_length=50)
    return combined

